const SHOE_SIZE_TABLES ={mens: [{us: 6, uk: 5.5, eu: 39, cm: 24},{us: 7, uk: 6, eu: 40, cm: 25},{us: 8, uk: 7, eu: 41, cm: 26},{us: 9, uk: 8, eu: 42, cm: 27},{us: 10, uk: 9, eu: 43, cm: 28},{us: 11, uk: 10, eu: 44.5, cm: 29},{us: 12, uk: 11, eu: 46, cm: 30},{us: 13, uk: 12, eu: 47, cm: 31}, ], womens: [{us: 5, uk: 3, eu: 35.5, cm: 22},{us: 6, uk: 4, eu: 36.5, cm: 23},{us: 7, uk: 5, eu: 37.5, cm: 24},{us: 8, uk: 6, eu: 38.5, cm: 25},{us: 9, uk: 7, eu: 40, cm: 26},{us: 10, uk: 8, eu: 41, cm: 27},{us: 11, uk: 9, eu: 42, cm: 28}, ], kids: [{us: 10, uk: 9.5, eu: 27, cm: 16.5},{us: 11, uk: 10.5, eu: 28, cm: 17.5},{us: 12, uk: 11.5, eu: 30, cm: 18.5},{us: 13, uk: 12.5, eu: 31, cm: 19.5},{us: "1Y", uk: 13, eu: 32, cm: 20},{us: "2Y", uk: 1, eu: 33, cm: 20.5},{us: "3Y", uk: 2, eu: 34, cm: 21.5}, ],};function setShoeCategory(category){["mens", "womens", "kids"].forEach((c) =>{const btn = document.getElementById(`shoecat-${c}`);btn.style.background = c === category ? "var(--phosphor)" : "";btn.style.color = c === category ? "var(--void)" : "";});const rows = SHOE_SIZE_TABLES[category] .map((r) => `<div class="exif-row"><span class="exif-key">US ${r.us}</span><span>UK ${r.uk} &nbsp; EU ${r.eu} &nbsp; ${r.cm} cm</span></div>`) .join("");document.getElementById("shoe-table").innerHTML = `<div class="exif-table">${rows}</div>`;}document.addEventListener("DOMContentLoaded", () => setShoeCategory("mens"));